  (function () {
    var boot = document.getElementById('boot');
    var start = document.getElementById('boot-start');
    function go() {
      if (boot) boot.classList.add('gone');
      setTimeout(function () { if (boot && boot.parentNode) boot.parentNode.removeChild(boot); }, 420);
      var world = window.__palmCity;
      if (world && world.audio) {
        try { world.audio.start(); world.audio.resume(); } catch (e) { void e; }
      }
      // entering from the boot card starts a fresh run rather than sitting on the title
      if (world && world.ui && world.ui.screen === 'title' && !window.__shotMode) {
        world.startNewGame();
      }
    }
    if (start) start.addEventListener('click', go);
    window.addEventListener('keydown', function (e) {
      if (boot && boot.classList.contains('gone')) return;
      if (e.code === 'Enter' || e.code === 'Space') go();
    });
    var shot = /[?&]shot=/.test(location.search);
    window.__shotMode = shot;
    if (shot) {
      if (boot && boot.parentNode) boot.parentNode.removeChild(boot);
      // the shot pass drives its own scene; keep the simulation on the title camera out of the way
      setTimeout(function () {
        var world = window.__palmCity;
        if (world) world.ui.screen = 'playing';
      }, 0);
    }
  })();
</script>
</body>
</html>
