  };

  // ---- one-shot sounds -------------------------------------------------------
  // Each effect builds its own nodes and lets them die; nothing is cached.
  AudioEngine.prototype.play = function (spec) {
    if (!this.ctx) { this.pending.push(spec); return; }
    if (!this.sfxOn) return;
