    }
  };
  AudioEngine.prototype.missionFail = function () {
    var notes = [392, 330, 262];
    for (var k = 0; k < notes.length; k++) {
      this.play({ type: 'sawtooth', freq: notes[k], freqEnd: notes[k] * 0.94, dur: 0.26, gain: 0.1 });
