      var amp = 4 + (k % 3) * 2;
      ctx.beginPath();
      for (var sx = x0; sx < CFG.WORLD_W; sx += 26) {
        var yy = wy + Math.sin((sx + t * 40) / 60) * amp;
        if (sx === x0) ctx.moveTo(sx, yy);
        else ctx.lineTo(sx, yy);
      }
      ctx.stroke();
    }
    ctx.restore();

    // foam along the waterline
    ctx.save();
    ctx.strokeStyle = 'rgba(233,250,249,0.65)';
    ctx.lineWidth = 7;
    ctx.beginPath();
